try {
  // Keep only rows that have enrichment data but no match score yet
  const data = $input.filter(item => {
    const row = item.json;
    // Must have summary (enriched) and no match_score yet
    return row.summary && row.summary.trim() !== '' && (!row.match_score || row.match_score === '');
  });

  if (data.length === 0) {
    return [{ json: { _no_new_jobs: true } }];
  }

  return data.slice(0, 20);
} catch(e) {
  return [{ json: { _error: e.message } }];
}

// ═══════════════════════════════════════════════════════════════════════
//  RESUME DATA — Edit this to match YOUR profile
// ═══════════════════════════════════════════════════════════════════════

const resume = {
  name: "YOUR NAME",
  email: "your.email@example.com",
  total_years_experience: 5,
  current_title: "Senior Software Engineer",
  target_roles: ["Software Engineer", "Full Stack Developer", "Backend Engineer", "SDE"],
  skills: [
    "JavaScript", "TypeScript", "React", "Node.js", "Python", "Java",
    "PostgreSQL", "MongoDB", "Redis", "AWS", "Docker", "Kubernetes",
    "REST APIs", "GraphQL", "Git", "CI/CD", "Linux"
  ]
};

// ═══════════════════════════════════════════════════════════════════════
//  SCORING ENGINE
// ═══════════════════════════════════════════════════════════════════════

function jaccardSimilarity(a, b) {
  const setA = new Set(a.map(s => s.toLowerCase().trim()));
  const setB = new Set(b.map(s => s.toLowerCase().trim()));
  let intersection = 0;
  const union = new Set([...setA, ...setB]);
  for (const item of setA) { if (setB.has(item)) intersection++; }
  return union.size === 0 ? 0 : intersection / union.size;
}

return $input.map(item => {
  try {
    const job = item.json;
    if (job._no_new_jobs) return item;

    const jobSkills = (job.required_skills || '').split(',').map(s => s.trim()).filter(Boolean);
    const candidateSkills = resume.skills || [];
    const candidateExperience = resume.total_years_experience || 0;
    const requiredYoe = Number(job.required_years_experience) || 0;

    // 1. Skill Match (40%)
    let matchedSkills = [], missingSkills = [];
    for (const skill of jobSkills) {
      if (candidateSkills.some(cs => cs.toLowerCase().includes(skill.toLowerCase()))) {
        matchedSkills.push(skill);
      } else {
        missingSkills.push(skill);
      }
    }
    const skillScore = jobSkills.length > 0 ? (matchedSkills.length / jobSkills.length) * 100 : 50;

    // 2. Experience Match (30%)
    const experienceScore = requiredYoe > 0 ? Math.min((candidateExperience / requiredYoe) * 50, 100) : 50;

    // 3. Title Relevance (20%)
    const jobTitle = (job.title || '').toLowerCase();
    const keywords = [...(resume.target_roles || []), ...(resume.current_title || '').split(' ')].map(k => k.toLowerCase());
    const titleMatchCount = keywords.filter(kw => jobTitle.includes(kw)).length;
    const titleScore = Math.min((titleMatchCount / Math.min(keywords.length, 10)) * 100, 100);

    // 4. Seniority Fit (10%)
    const seniority = (job.seniority || '').toLowerCase();
    let seniorityScore = 50;
    if (seniority !== 'not specified' && seniority !== '') {
      if (candidateExperience <= 2) {
        seniorityScore = seniority === 'junior' ? 100 : seniority === 'mid' ? 70 : 30;
      } else if (candidateExperience <= 5) {
        seniorityScore = (seniority === 'mid' || seniority === 'senior') ? 100 : seniority === 'junior' ? 70 : 40;
      } else {
        seniorityScore = (seniority === 'senior' || seniority === 'lead') ? 100 : seniority === 'mid' ? 70 : 40;
      }
    }

    // Composite
    const score = Math.round(skillScore * 0.40 + experienceScore * 0.30 + titleScore * 0.20 + seniorityScore * 0.10);

    // Action
    let action = 'skip';
    if (score >= 80) action = 'auto';
    else if (score >= 60) action = 'review';

    return {
      json: {
        ...job,
        match_score: score,
        match_action: action,
        matching_skills: matchedSkills.join(', '),
        missing_skills: missingSkills.join(', '),
        candidate_yoe: candidateExperience,
        matched_at: new Date().toISOString()
      }
    };
  } catch(e) {
    return { json: { ...item.json, match_error: e.message } };
  }
});
